 10	    private RabinKarp() {
 11	    }
 12	
 13	    public static List<Integer> search(CharSequence pattern, CharSequence text) {
 14	        SearchInput input = SearchInput.of(pattern, text);
 15	
 16	        if (input.hasEmptyPattern()) {
 17	            return allStartIndexes(input.textLength());
 18	        }
 19	
 20	        if (!input.hasMatchableWindow()) {
 21	            return noMatches();
 22	        }
 23	
 24	        SearchState searchState = input.newSearchState();
 25	        return collectMatches(searchState);
 26	    }
 27	
 28	    private static List<Integer> collectMatches(SearchState searchState) {
 29	        List<Integer> matches = new ArrayList<>(searchState.windowCount());
 30	        while (searchState.hasCurrentWindow()) {
 31	            if (searchState.isMatch()) {
 32	                matches.add(searchState.currentStart());
 33	            }
 34	            searchState.advance();
 35	        }
 36	        return matches;
 37	    }
