 43	    private static List<Integer> allStartIndexes(int textLength) {
 44	        List<Integer> matches = new ArrayList<>(textLength + 1);
 45	        for (int i = 0; i <= textLength; i++) {
 46	            matches.add(i);
 47	        }
 48	        return matches;
 49	    }
