129	    private static final class SearchState {
130	        private final SearchPattern pattern;
131	        private final TextWindow window;
132	        private int startIndex;
133	
134	        private SearchState(String text, SearchPattern pattern) {
135	            this.pattern = pattern;
136	            this.window = new TextWindow(text, pattern.length());
137	        }
138	
139	        private boolean hasCurrentWindow() {
140	            return startIndex <= window.lastStartIndex();
141	        }
142	
143	        private int windowCount() {
144	            return window.lastStartIndex() + 1;
145	        }
146	
147	        private int currentStart() {
148	            return startIndex;
149	        }
150	
151	        private boolean isMatch() {
152	            return pattern.hash() == window.hash()
153	                && pattern.matches(window.text(), startIndex);
154	        }
155	
156	        private void advance() {
157	            if (startIndex < window.lastStartIndex()) {
158	                window.slide(pattern.highOrderMultiplier(), startIndex);
159	            }
