171	            this.windowLength = windowLength;
172	            this.hash = RollingHash.compute(text, windowLength);
173	        }
174	
175	        private int lastStartIndex() {
176	            return text.length() - windowLength;
177	        }
178	
179	        private int hash() {
180	            return hash;
181	        }
182	
183	        private String text() {
184	            return text;
185	        }
186	
187	        private void slide(int highOrderMultiplier, int startIndex) {
188	            hash = RollingHash.roll(
189	                hash,
190	                text.charAt(startIndex),
191	                text.charAt(startIndex + windowLength),
192	                highOrderMultiplier
193	            );
194	        }
195	    }
