197	    private static final class RollingHash {
198	        private RollingHash() {
199	        }
200	
201	        private static int compute(String value, int length) {
202	            int hash = 0;
203	            for (int i = 0; i < length; i++) {
204	                hash = (RADIX * hash + value.charAt(i)) % MODULUS;
205	            }
206	            return hash;
207	        }
208	
209	        private static int roll(
210	            int currentHash,
211	            char outgoingChar,
212	            char incomingChar,
213	            int highOrderMultiplier
214	        ) {
215	            int nextHash = (
216	                RADIX * (currentHash - outgoingChar * highOrderMultiplier) + incomingChar
217	            ) % MODULUS;
218	
219	            if (nextHash < 0) {
220	                nextHash += MODULUS;
221	            }
222	
223	            return nextHash;
224	        }
225	    }
226	
227	    private static int computeHighOrderMultiplier(int patternLength) {
228	        int highOrderMultiplier = 1;
229	        for (int i = 0; i < patternLength - 1; i++) {
230	            highOrderMultiplier = (highOrderMultiplier * RADIX) % MODULUS;
231	        }
232	        return highOrderMultiplier;
233	    }
